// Dávka E – zvířátka, do auta a velká dobrodružství
window.STORIES_DRAFT = (window.STORIES_DRAFT || []).concat([
  {
    id: 'zmrzlinovy-dest',
    delka: 10,
    pro: 'vse',
    pozn: 'Nad obcí začne pršet zmrzlina a nastane sladký zmatek. Dítě vymyslí, jak ji spravedlivě rozdělit všem, a nakonec se nad obcí rozzáří duha z polevy.',
    free: false,
    cats: ['sranda', 'dobro'],
    ages: [3, 8],
    mood: 'adventure',
    cover: { emoji: '🍦', g1: '#f06292', g2: '#ffe082' },
    title: (c) => `Zmrzlinový déšť`,
    text: (c) => [
      { t: `Byl horký letní den. Tak horký, že i kočky ležely ve stínu rozteklé jako máslo a pejsci neměli sílu ani štěknout. Vzduch se nad silnicí tetelil jako polévka na plotně.` },
      { t: `${c.H} ${c.g('seděl', 'seděla', 'seděli')} na schodech před domem. ${c.g('Foukal', 'Foukala', 'Foukali')} si do ofiny a ${c.g('vzdychal', 'vzdychala', 'vzdychali')}: „Kdyby tak aspoň trochu pršelo.“` },
      { t: `Vtom se nad střechami objevil mrak. Ale nebyl šedivý jako obyčejné mraky. Byl růžový, trochu žlutý a na kraji měl hnědý proužek. Vypadal jako obrovský kopeček zmrzliny, který někomu sklouzl z kornoutu.` },
      { t: `Mrak se zastavil přímo nad obcí. Chvilku jen tak visel a nic. Pak udělal „blob“. A pak začalo pršet.`, sfx: 'magic' },
      { t: `Jenže nepršela voda. Pršela zmrzlina! Plop, plop, plop! Jahodové kuličky, vanilkové kuličky, čokoládové kuličky. Padaly z nebe jako veliké barevné kroupy.` },
      { t: `Lidé vybíhali z domů a nemohli uvěřit vlastním očím. Někdo křičel, někdo se smál a jedna babička nastavila hrnek, jako když se chytá dešťová voda na zalévání. Za chvilku měla hrnek plný jahodové.` },
      { t: `Takový déšť ještě nikdo ${c.inTown} nezažil.` },
      { t: `Jedna pistáciová kulička přistála panu sousedovi rovnou na pleši. Plesk! Soused se zarazil, olízl si prst a řekl: „Hm. Pistácie. Mohla by být trochu sladší.“` },
      { t: `Paní z obchodu otevřela deštník. Za minutu na něm měla takovou horu zmrzliny, že vypadala jako chodící pohár se šlehačkou.` },
      { t: `Pes od vedle běhal sem a tam a chytal kuličky za letu. Hap! Hap! Ještě nikdy nebyl tak šťastný. A ještě nikdy neměl tak studený čumák.` },
      { t: `${c.H} ${c.g('vyskočil', 'vyskočila', 'vyskočili')} ze schodů. „Hurá, zmrzlinový déšť!“ ${c.g('zavýskal', 'zavýskala', 'zavýskali')} a ${c.g('nastavil', 'nastavila', 'nastavili')} ${c.n('pusu', 'pusy')} k nebi.` },
      { t: `Jedna jahodová kulička ${c.h.dat} přistála rovnou na nose.` },
      { t: `Studila a voněla po letních jahodách. Mňam! Takovou dobrotu ještě nikdo nikdy neochutnal rovnou z nebe.` },
      { t: `Jenže brzy se ukázalo, že zmrzlinový déšť má i svoje mouchy. Zmrzlina byla všude. Na chodníku, na plotech, na autech i na prádle, které se sušilo na šňůře. A klouzalo to jako na bruslích.` },
      { t: `Pan pošťák šlápl do kaluže z vanilky a sjel po ní jako po skluzavce, až zastavil v měkkém keři. Nic se mu nestalo. Jen mu dopisy vyletěly z brašny a slepily se do jedné veliké sladké obálky.`, sfx: 'paper' },
      { t: `Děti z ulice olizovaly lampy, kočky olizovaly děti a jedna kachna z návsi si sedla do kopečku stracciatelly a odmítla odejít.` },
      { t: `A zmrzliny pořád přibývalo. Kopečky rostly a rostly. Brzy byly vysoké jako sněhuláci. A pak jako garáže.` },
      { t: `Na návsi stál traktor a z kopečku zmrzliny mu koukal jen komín. Přijeli i hasiči, ale nevěděli, co mají hasit. Zmrzlina přece nehoří. Tak aspoň kropili kopečky studenou vodou, aby se nerozpustily moc brzo.`, sfx: 'horn' },
      { t: `Děti ze školky postavily ze zmrzliny sněhuláka. Měl knoflíky z čokolády, nos z oplatky a místo koštěte držel lízátko. Byl to první zmrzlinák na světě.` },
      { t: `Dokonce i mravenci si všimli, že se něco děje. Seřadili se do dlouhé řady a nosili si do mraveniště malinké kapičky karamelu. Každý mravenec jednu. Mravenci se totiž o jídlo dělí odjakživa a vůbec se nemusí domlouvat.` },
      { t: `„Tohle nesníme ani za sto let,“ povzdechl si soused. „A za chvíli se to začne rozpouštět. Bude tu jedno velké sladké jezero a my v něm budeme plavat jako lentilky.“` },
      { t: `${c.H} se ${c.g('zamyslel', 'zamyslela', 'zamysleli')}. Zmrzlina je přece dobrá věc. Byla by škoda, kdyby se jen tak rozteklá válela po silnici. Muselo se to udělat chytře.` },
      { t: `Pak to přišlo. Nápad! „Rozdělíme ji, ať má každý, kolik sní, a zbytek schováme do mrazáků na zimu!“ ${c.g('vykřikl', 'vykřikla', 'vykřikli')} a hned ${c.g('běžel', 'běžela', 'běželi')} pro misku.`, sfx: 'ding' },
      { t: `A tak to začalo. Lidé z celé ulice vynesli všechno, do čeho se dá zmrzlina dát. Hrnky, misky, kastroly, kyblíčky na písek. Pan učitel přinesl dokonce i svůj klobouk.` },
      { t: `${cap(c.p1.full)} ${c.p1.g('přinesl', 'přinesla')} největší vařečku, jakou doma měli. Nabíralo se s ní nejlíp. Do každé misky jeden kopeček, dva kopečky, tři.` },
      { t: `Aby se nikdo nestrkal, ${c.g('vymyslel', 'vymyslela', 'vymysleli')} i pořadí. Kdo přijde, stoupne si do řady. Nejdřív nejmenší děti, pak babičky a dědečkové, pak všichni ostatní. A kdo už má, uhne a udělá místo dalšímu.` },
      { t: `Malé děti dostaly malé porce, aby je nebolelo bříško. Babičky dostaly vanilku, protože vanilku mají babičky nejradši. A pes od vedle dostal kopeček bez čokolády, protože čokoláda pejskům nedělá dobře.` },
      { t: `Kachna z návsi dostala celou mísu pistácie jen pro sebe. Konečně se zvedla, spokojeně zakejhala a odkolébala se k rybníku.` },
      { t: `Dokonce i ptáci si přiletěli pro svůj díl. Vrabci zobali drobečky z kornoutů a kos si odnesl do hnízda kousek oplatky, aby měla mláďata zítra k snídani něco dobrého.` },
      { t: `${c.H} ${c.g('běhal', 'běhala', 'běhali')} od domu k domu. Tady chybí lžička, tady potřebují ještě jednu misku, tamhle pán nemá vůbec nic. Nikdo nesměl zůstat bez zmrzliny.` },
      { t: `Pan starosta vylezl na lavičku a zavolal: „Sousedé! Tohle je ten nejlepší nápad, jaký kdy naše obec měla!“ A všichni zatleskali lepkavýma rukama. Plesk, plesk, plesk.` },
      { t: c.near.length ? `Zpráva o zmrzlinovém dešti se rychle roznesla po okolí: ${listCz(c.near.slice(0, 3))}.` : `Zpráva o zmrzlinovém dešti se rychle roznesla po celém okolí.` },
      { t: `Lidé přijížděli na kolech i s kočárky. Každý si přivezl misku a každý odjížděl s úsměvem od ucha k uchu.` },
      { t: `Mrazáky v celé obci se plnily. Do jednoho se vešla jahodová, do druhého vanilková, do třetího čokoládová. Jeden mrazák byl tak plný, že nešel zavřít. Tak si na něj sedl pan starosta, aby nevypadla ani kulička.` },
      { t: `Teprve úplně nakonec ${c.g('si nabral', 'si nabrala', 'si nabrali')} ${c.H} misku i pro sebe.` },
      { t: `Byla to ta nejlepší zmrzlina celého dne. Studená, sladká a trochu rozteklá, přesně jak má být.` },
      { t: `A jakou příchuť ${c.g('by sis vybral', 'by sis vybrala', 'byste si vybrali', 'byste si vybraly')} ${c.n('ty', 'vy')}?`, pause: 4 },
      { t: `Když byla rozdělená poslední kulička, mrak nad obcí najednou zakručel. Byl úplně prázdný. Zmenšil se, zbělal a vypadal docela spokojeně. Jako když se někdo dobře nají.` },
      { t: `A pak vysvitlo slunce. Paprsky prošly posledními kapkami polevy, které ještě visely ve vzduchu, a na obloze se rozzářila duha.`, sfx: 'sparkle' },
      { t: `Ale nebyla to obyčejná duha. Byla jahodová, pomerančová, citronová, pistáciová a borůvková. A voněla tak sladce, že se všichni zastavili a jen se dívali nahoru.` },
      { t: `„To je ta nejhezčí duha, jakou ${c.n('jsem', 'jsme')} kdy ${c.g('viděl', 'viděla', 'viděli')},“ ${c.g('zašeptal', 'zašeptala', 'zašeptali')} ${c.H}.` },
      { t: `Soused si otřel z pleše poslední kapku pistácie a usmál se. „Víte co? Nejlepší na tom nebyla zmrzlina. Nejlepší bylo, že jsme se o ni rozdělili.“` },
      { t: `Pak přišlo velké uklízení. Všichni vzali kýble s vodou a kartáče a drhli chodníky, ploty i lampy. Pes od vedle pomáhal po svém: všechno, co zůstalo na zemi, olízal dočista. A pošťák si nakonec rozlepil všechny dopisy. Voněly jahodami ještě týden.` },
      { t: `Ten večer usínala celá obec spokojeně a trochu ulepeně. V mrazácích čekala zmrzlina na celou zimu. A na obloze ještě dlouho svítil sladký proužek duhy.` },
      { t: `${c.H} ${c.g('ležel', 'ležela', 'leželi')} v posteli a ${c.g('přemýšlel', 'přemýšlela', 'přemýšleli')}, co by mohlo pršet příště. Třeba to nejlepší jídlo na světě: ${c.food}.` },
      { t: `Kdo ví. Mraky jsou plné překvapení. Ale jedno je jisté: ať bude pršet cokoli, rozdělit se o to je vždycky nejsladší.` },
    ],
  },
  {
    id: 'kdo-to-dela',
    delka: 5,
    pro: 'vse',
    pozn: 'Hra do auta: teta Terezka popisuje zvířátka podle zvuku a vzhledu, dítě hádá, po pauze přijde odpověď se zajímavostí. Poslední hádanka je oblíbené zvíře dítěte.',
    free: false,
    cats: ['auto', 'zvirata'],
    ages: [2, 6],
    mood: 'road',
    cover: { emoji: '🐮', g1: '#2e7d32', g2: '#c5e1a5' },
    title: (c) => `Kdo to dělá?`,
    text: (c) => [
      { t: `Pozor, posádko! Začíná zvířátková hra „Kdo to dělá?“. Já řeknu, jak zvířátko dělá a jak vypadá, a ${c.n('ty budeš', 'vy budete')} hádat.`, sfx: 'car' },
      { t: `${c.n('Jsi', 'Jste')} ${c.g('připravený', 'připravená', 'připravení', 'připravené')}, ${c.h.voc}? Tak nastražte uši. První hádanka!` },
      { t: `„Bú! Bú!“ Je velká, má rohy a na krku jí cinká zvoneček. Celý den spásá trávu na louce a dává nám mléko. Kdo to je?`, pause: 5 },
      { t: `Kráva! Správně! A víte, že kráva pořád přežvykuje? Žvýká trávu dokola, jako by měla žvýkačku.`, sfx: 'ding' },
      { t: `„Mňau!“ Je malá, má měkoučký kožíšek a dlouhé vousky. Když je spokojená, přede jako malý motorek. Vrrr, vrrr. Kdo to je?`, pause: 5 },
      { t: `Kočička! Výborně. Kočky umějí spát skoro celý den. A v noci se jim oči lesknou jako dvě baterky.` },
      { t: `„Kikirikí!“ Má červený hřebínek, pyšně se prochází po dvoře a každé ráno budí celou vesnici, i když se nikomu nechce vstávat. Kdo to je?`, pause: 5 },
      { t: `Kohout! Přesně tak. Kohout si myslí, že bez něj by slunce nevyšlo. Tak ať si to myslí.` },
      { t: `„Kuňk, kuňk!“ Je zelená, sedí na leknínu a umí skákat daleko, daleko. Mouchy chytá dlouhým jazykem. Šlup! Kdo to je?`, pause: 5 },
      { t: `Žába! Správně. Malé žabičky se jmenují pulci a vypadají jako černé čárky s ocáskem.`, sfx: 'ding' },
      { t: `„Haf, haf!“ Vrtí ocasem, když má radost, nosí klacíky a hlídá dům. Kdo to je?`, pause: 5 },
      { t: `Pejsek! No jasně. Pejsek pozná kamaráda podle čuchu dřív, než ho uvidí.` },
      { t: `„Bé, bé!“ Je kudrnatá jako obláček a z její vlny se pletou teplé svetry a ponožky. Kdo to je?`, pause: 5 },
      { t: `Ovečka! Ano. Kdyby se ovečka nestříhala, vypadala by brzy jako obrovský chlupatý míč.` },
      { t: `„Kvák, kvák!“ Má placaté nožky, ráda se čvachtá v rybníce a když plave, vypadá, že vůbec nehýbe nohama. Kdo to je?`, pause: 5 },
      { t: `Kachna! Správně. Pod vodou ale pádluje nožkama jako o závod.` },
      { t: `Teď pozor, těžší hádanka. Skoro nedělá žádný zvuk, jen tiše funí. Má na zádech bodliny a v noci chodí po zahradě hledat brouky. Kdo to je?`, pause: 5 },
      { t: `Ježek! Ten byl těžký, co? Když se ježek lekne, stočí se do kuličky a je z něj pichlavý kaštan.`, sfx: 'ding' },
      { t: `„Chro, chro!“ Je růžové, má zatočený ocásek a nejradši se válí v blátě. Kdo to je?`, pause: 5 },
      { t: `Prasátko! Válí se v blátě, aby se ochladilo. Bláto je jeho krém na opalování.` },
      { t: `„Hú, hú!“ Ve dne spí, v noci kouká velikánskýma očima a umí otočit hlavu skoro dokola. Kdo to je?`, pause: 5 },
      { t: `Sova! Správně. Sova vidí ve tmě mnohem líp než my lidé.`, sfx: 'owl' },
      { t: `A teď úplně poslední hádanka. Je to zvířátko, které ${c.n('má', 'mají')} ${c.H} ze všech nejradši. Kdo to je?`, pause: 5 },
      { t: `${cap(c.animal)}! No jasně.` },
      { t: `Hra „Kdo to dělá?“ končí. Posádka hádala skvěle a všechna zvířátka posílají pozdrav: bú, mňau, kuňk a hú!`, sfx: 'horn' },
    ],
  },
  {
    id: 'noc-v-lese',
    delka: 10,
    pro: 'vse',
    pozn: 'Večerní procházka lesem, kde se zvířátka chystají spát a každé má svůj uspávací rituál (veverka, ježek, srnka, liška, zajíc, kachny, sova). Nakonec usíná i dítě.',
    free: false,
    cats: ['zvirata', 'noc'],
    ages: [2, 7],
    mood: 'lullaby',
    cover: { emoji: '🦔', g1: '#1a237e', g2: '#558b2f' },
    title: (c) => `Noc v lese`,
    text: (c) => [
      { t: `Bylo teplé letní odpoledne a slunce už se pomalu sklánělo k zemi. Večer přicházel tiše, po špičkách, jako když se někdo bojí vzbudit miminko. Stíny se natahovaly, jako když se protahuje kočka po spaní.` },
      { t: `${c.H} ${c.g('šel', 'šla', 'šli')} s ${c.p1.ins} na procházku do lesa. Jen kousek, jen na chvilku. Podívat se, jak les chodí spát.` },
      { t: `Na kraji lesa to vonělo jehličím a hříbky. Cestička byla měkká a pod nohama křupaly šišky. Křup, křup. A ptáci zpívali svou poslední písničku.`, sfx: 'birds' },
      { t: `„Poslouchej,“ ${c.p1.g('zašeptal', 'zašeptala')} ${c.p1.nom}. „Teď les zpívá na dobrou noc.“` },
      { t: `Ptáci zpívali čím dál tišeji. Kos, drozd, malá červenka. Jeden po druhém si strčili hlavičku pod křídlo a schovali se do svých hnízd.` },
      { t: `U cestičky stálo velké mraveniště. Mravenci pobíhali sem a tam a nosili poslední jehličky. Mravenčí rituál je zavírání dveří. Každý večer ucpou všechny vchody jehličím, aby jim dovnitř nefoukalo. A pak se stulí k sobě, tisíc malých mravenečků v jedné velké postýlce.` },
      { t: `„A co dělají mravenci, když nemůžou usnout?“ ${c.g('zeptal', 'zeptala', 'zeptali')} se ${c.H}.` },
      { t: `„Počítají ostatní mravence,“ ${c.p1.g('usmál', 'usmála')} se ${c.p1.nom}. „A než napočítají do tisíce, spí.“` },
      { t: `První, koho potkali, byla veverka. Seděla na větvi a v tlapkách držela poslední oříšek dne.` },
      { t: `Veverka má svůj uspávací rituál. Oříšek si schová do dutiny, pod polštářek z mechu. Pak se stočí do klubíčka a zabalí se do huňatého ocásku. Jako do deky. A je jí teplo až po ouška.` },
      { t: `„Dobrou noc, veverko,“ ${c.g('zašeptal', 'zašeptala', 'zašeptali')} ${c.H}. A veverka už spala.` },
      { t: `Cestička vedla dál, mezi kapradí. Tam pod hromádkou listí něco tiše funělo. Fu, fu, fu. To byl malý ježeček.` },
      { t: `Ježeček má taky svůj rituál. Nahrabe si listí, aby měl měkkou postýlku. Lehne si a počítá bodlinky. Místo oveček. Jedna bodlinka, dvě bodlinky, tři… A u sedmé bodlinky už spí.` },
      { t: `Vysoko na kmeni ještě ťukal datel. Ťuk, ťuk, ťuk. Pak ťukl naposledy, potichounku, jako když se klepe na dveře ložnice. Ťuk. To byl datlí rituál: popřát stromu dobrou noc. A pak se schoval do své dutinky.` },
      { t: `Na pařezu seděl malý brouček a skládal si křidélka. Nejdřív jedno, pak druhé, pečlivě, jako když se skládá kapesník. Pak se schoval pod kousek kůry a zhasl svou malou tečku na zádech.` },
      { t: `Pomalu šli dál, až na malou paseku. Ve vysoké trávě tam ležela srnka a vedle ní dvě koloušátka s bílými tečkami na zádech.` },
      { t: `Srnka má nejhezčí rituál ze všech. Olízne koloušky na čele, jednoho, pak druhého. Složí jim nožky pod bříško. A pak se k nim přitulí, aby jim bylo teplo. Celá paseka voní trávou a mlékem.` },
      { t: `${c.H} se ${c.g('usmál', 'usmála', 'usmáli')}. Tohle znal${c.g('', 'a', 'i', 'y')} moc dobře. Takhle se přece přitulí ${c.p1.nom}.` },
      { t: `U staré nory se mezitím činil jezevec. Jezevec je velký pořádník. Než jde spát, vynese z nory staré seno a nanosí si nové, suché a voňavé. Pěkně si ho načechrá, jako když se natřásá polštář. Teprve pak zaleze dovnitř a spokojeně zafuní.` },
      { t: `Za pasekou, u starého pařezu, se ozvalo tiché zívnutí. Áááá. Liška. Rezavá a krásná, s bílou špičkou na ocase.` },
      { t: `Liščí rituál je takový. Liška se zatočí třikrát dokola. Jednou, dvakrát, třikrát. Pak si lehne do klubíčka a přikryje si čumáček huňatým ohonem. Ohon je její peřinka i polštář zároveň.` },
      { t: `Liška ještě jednou otevřela jedno oko a podívala se na ${c.h.acc}.` },
      { t: `Jako by chtěla říct: „Neboj, já jen odpočívám. Zítra si zase spolu hrajeme na schovávanou.“` },
      { t: `Na kraji pole seděl zajíček. Ušima stříhal sem a tam a poslouchal, jestli už je všude ticho.` },
      { t: `Zajíček má dlouhé uši, a tak je musí uložit jako první. Sklopí je na záda, jedno, pak druhé, jako když se skládá peřinka. Pak zavře oči a jen čumáček ještě chvilku dělá ňuf, ňuf.` },
      { t: `Na lesním rybníčku se ještě houpaly kachny. Kachní rituál je jednoduchý. Kachna si strčí hlavičku pod křídlo. A pak spí na vodě, jako by ležela v kolébce, a vlnky ji houpou tam a zpátky.` },
      { t: `${c.H} ${c.g('zívl', 'zívla', 'zívli')}.` },
      { t: `Ani si toho ${c.g('nevšiml', 'nevšimla', 'nevšimli')}. Zívání je totiž nakažlivé, jako smích. Když zívá celý les, začnou zívat i děti.` },
      { t: `Mezitím se setmělo. Na nebi se rozsvítila první hvězda. Pak druhá. Pak celá hrstka hvězd, jako když někdo rozsype třpytky.`, sfx: 'sparkle' },
      { t: `Nad stromy vyšel měsíc. Kulatý a stříbrný, jako velký polštář na nebi. Posvítil na cestičku, na kapradí i na pařez, kde spala liška. Měsíc je lesní noční lampička. A nezhasne, dokud všichni neusnou.` },
      { t: `A vtom se z vysoké borovice ozvalo: „Hú, hú.“ Na větvi seděla sova. Velká, moudrá, s očima jako dva měsíčky.`, sfx: 'owl' },
      { t: `Sova jediná nespí. Sova má jiný rituál. Když všichni usnou, sedne si na nejvyšší větev a hlídá. Celou noc dává pozor, aby měl les klidný spánek.` },
      { t: `„Hú, hú,“ zahoukala sova potichu. To v sovím jazyce znamená: „Spěte klidně, já tu jsem.“` },
      { t: `„Dobrou noc, sovičko,“ ${c.g('zašeptal', 'zašeptala', 'zašeptali')} ${c.H}. A sova pomalu mrkla na pozdrav.` },
      { t: `Cestou zpátky jim svítily světlušky. Malinké zelené lampičky, které se rozsvěcejí jen v noci. Poletovaly kolem cestičky, jako by šeptaly: „Tudy, tudy, tady je cesta domů.“` },
      { t: `Kousek od cesty zurčel potůček. Potůček nespí nikdy, ale v noci zpívá tišeji. Žbluňk, žbluňk, šeptá kamínkům. Jako když se zpívá ukolébavka a hlas se pomalu ztišuje.` },
      { t: `${cap(c.p1.nom)} ${c.p1.g('vzal', 'vzala')} ${c.h.acc} za ruku.` },
      { t: `Šlo se pomalu. Krok, krok, krok. Les za nimi byl tichý a tmavý. Ale nebyla to strašidelná tma. Byla to tma měkká a hebká, jako peřina, pod kterou spí tisíc zvířátek.` },
      { t: `Domů už ${c.H} ${c.g('došel', 'došla', 'došli')} ${c.g('ospalý', 'ospalá', 'ospalí', 'ospalé')}.` },
      { t: `A víš co? Děti mají taky svůj uspávací rituál. Jako veverka, jako ježeček, jako liška. Nejdřív pyžamo. Pak zuby, šup nahoru, šup dolů. Pak pusinka na dobrou noc.` },
      { t: `A pak ${c.n('si lehneš', 'si lehnete')} do postýlky. Peřina je teplá jako veverčí ocásek. Polštář je měkký jako listí, ve kterém spí ježeček.` },
      { t: `Ještě chvilku si ${c.n('můžeš', 'můžete')} vzpomenout na všechna zvířátka. Veverka spí. Ježeček spí. Srnka s koloušky spí. Liška spí. Zajíček spí.` },
      { t: `A někde daleko spí i zvířátko, které ${c.n('máš', 'máte')} ze všech nejradši: ${c.animal}.` },
      { t: `Jen sova bdí. Sedí na větvi a hlídá. ${c.g('Aby ses nemusel', 'Aby ses nemusela', 'Abyste se nemuseli', 'Abyste se nemusely')} ničeho bát.` },
      { t: `Tak teď ${c.n('zavři', 'zavřete')} oči. ${c.n('Dýchej', 'Dýchejte')} pomalu, jako srnka v trávě. Nádech… a výdech. Nádech… a výdech.`, pause: 6 },
      { t: `Veverka dýchá pomalu. Ježeček dýchá pomalu. Srnka dýchá pomalu. A ${c.n('ty', 'vy')} taky. Pomalu, pomaloučku.`, pause: 5 },
      { t: `Ruce jsou těžké. Nohy jsou těžké. Víčka jsou těžká, jako když na ně usedne měkký chomáček mechu. A les tiše šumí: šššš, šššš.`, pause: 5 },
      { t: `Les spí. Hvězdy svítí. A sova tiše houká: hú, hú. Dobrou noc.`, pause: 4 },
      { t: `Dobrou noc, ${c.h.voc}.`, pause: 4 },
    ],
  },
  {
    id: 'dinosaurus-na-zahrade',
    delka: 15,
    pro: 'm',
    pozn: 'Ráno se na zahradě z „kamene“ vylíhne malý dinosaurus Kamínek, který rychle roste. Dítě se o něj stará a podle spirály na skořápce najde bránu, kterou se Kamínek vrátí ke své mamince do pravěku.',
    free: false,
    cats: ['dobro', 'sranda'],
    ages: [3, 8],
    mood: 'adventure',
    cover: { emoji: '🦕', g1: '#33691e', g2: '#aed581' },
    title: (c) => `Dinosaurus na zahradě`,
    text: (c) => {
      const a = c.g('', 'a', 'i', 'y');
      return [
        { t: `Bylo sobotní ráno a celý dům ještě spal. Jen kos na plotě zpíval tak hlasitě, jako by chtěl vzbudit celou ulici.`, sfx: 'birds' },
        { t: `${c.H} ${c.g('otevřel', 'otevřela', 'otevřeli')} oči a ${c.g('vykoukl', 'vykoukla', 'vykoukli')} z okna.` },
        { t: `Na zahradě, hned vedle záhonu s mrkví, ležel kámen. Velký, kulatý a šedý, s hnědými skvrnkami. Včera tam ještě nebyl. Tím si byl${a} ${c.g('jistý', 'jistá', 'jistí', 'jisté')}.` },
        { t: `V pyžamu a v gumákách ${c.g('vyběhl', 'vyběhla', 'vyběhli')} ven. Tráva byla mokrá od rosy a studila do kotníků. Kámen byl teplý. A když na něj ${c.g('položil', 'položila', 'položili')} ${c.n('dlaň', 'dlaně')}, ucítil${a}, že se uvnitř něco hýbe.` },
        { t: `Ťuk. Ťuk, ťuk. Kámen zapraskal. Na boku se objevila klikatá čárka, pak druhá, a pak kousek kamene odskočil jako pokličky z hrnce.` },
        { t: `Z díry vykoukla malá zelená hlavička. Měla dvě kulatá očka, malé nozdry a na čumáčku kousek skořápky jako čepičku. „Píp,“ řekla hlavička. A pak ještě jednou, tišeji: „Píp?“`, sfx: 'magic' },
        { t: `Kámen totiž nebyl kámen. Bylo to vejce. A z vejce se právě vylíhl dinosaurus!` },
        { t: `Dinosaurek se zkusil postavit. Jedna nožka, druhá nožka, třetí… a čtvrtá se zamotala do ocásku. Žuch! Sedl si do trávy a překvapeně zamrkal. Napodruhé už to šlo. Napotřetí už dokonce skákal.` },
        { t: `„Ahoj, neboj se, ${c.n('já ti nic neudělám', 'my ti nic neuděláme')},“ ${c.g('zašeptal', 'zašeptala', 'zašeptali')} ${c.H}.` },
        { t: `Dinosaurek vylezl ze skořápky celý. Byl velký asi jako kočka, měl dlouhý ocásek, na zádech řadu měkkých zelených ostnů a čtyři tlusté nožky. Zavrtěl se, kýchl a z nosu mu vyletěl obláček prachu.` },
        { t: `Pak se přitulil k ${c.h.dat}.` },
        { t: `Malá mláďata to tak dělají. Koho uvidí jako prvního, toho mají hned rádi. A tohle mládě mělo rádo opravdu moc.` },
        { t: `„Budeš se jmenovat Kamínek,“ ${c.g('rozhodl', 'rozhodla', 'rozhodli')} se ${c.H}.` },
        { t: `A dinosaurek spokojeně zapípal, protože to jméno se mu moc líbilo.` },
        { t: `Vtom na zahradu ${c.p1.g('vyšel', 'vyšla')} ${c.p1.full} s hrnkem kávy. Zastavil${c.p1.g('', 'a')} se, zamrkal${c.p1.g('', 'a')} a promnul${c.p1.g('', 'a')} si oči.` },
        { t: `„To je… dinosaurus?“ ozvalo se potichu, aby se mládě nevylekalo.` },
        { t: `„Jmenuje se Kamínek. A má hlad,“ ${c.g('vysvětlil', 'vysvětlila', 'vysvětlili')} ${c.H}.` },
        { t: `Kamínek opravdu hlad měl. Snědl tři listy salátu, pět mrkví ze záhonu, dvě jablka i s ohryzkem a jednu kytku, kterou mu nikdo nenabízel. Pak si spokojeně odříhl. Brk.` },
        { t: `Nakonec ochutnal i to nejlepší jídlo na světě: ${c.food}.` },
        { t: `Kamínek mlaskal, olizoval se a točil ocáskem jako vrtulkou. Tohle mu chutnalo ze všeho nejvíc.` },
        { t: `Po snídani se Kamínek pokusil zařvat. Dinosauři přece řvou. Nadechl se, nafoukl tváře, otevřel tlamičku a… „Píp.“ Zkusil to znovu. „Píííp.“ Zkroušeně sklopil hlavu.` },
        { t: `„Takhle ne. Musíš z bříška. Ráááá!“ ${c.g('předvedl', 'předvedla', 'předvedli')} mu a ${c.g('udělal', 'udělala', 'udělali')} strašidelný obličej. Kamínek se tak smál, že se překulil na záda a kopal nožkama do vzduchu.` },
        { t: `Jenže dinosauři rostou rychle. Hodně rychle. Po snídani byl Kamínek velký jako pes. Po svačině jako poník. A k obědu mu hlava koukala přes plot.` },
        { t: `Soused zrovna sekal trávu. Zvedl oči, uviděl nad plotem zelenou hlavu s ostny a sekačka mu zůstala stát. Kamínek na něj přátelsky zafuněl. Znělo to skoro jako „dobrý den“.` },
        { t: `Soused si sundal čepici, podrbal se na hlavě a zase si ji nasadil. „No,“ řekl pak. „Hlavně ať mi nesní jahody.“` },
        { t: `Pak přišla sousedovic kočka. Malá, mourovatá a vůbec se nebála. Sedla si před Kamínka a zasyčela: „Ššš!“ A velký dinosaurus se schoval za jabloň. Teda, schoval. Koukal zpoza ní celý, od hlavy až po ocas.` },
        { t: `Kočka si ho chvíli prohlížela, pak zívla a odešla. Kamínek si oddechl tak mocně, že z jabloně spadla tři jablka. Buch, buch, buch.` },
        { t: `Po obědě si Kamínek zdříml. Lehl si přes celou zahradu, od záhonu až k pískovišti, a chrápal tak, že se třásly okenní tabulky. Chrrr, fíí. Chrrr, fíí. Ptáci si mezitím sedali na jeho ostny jako na plot.` },
        { t: `Když se probudil, zanechal po sobě v trávníku stopy. Velké, jako lavor. Do jedné nateklo trochu vody a vrabci se v ní hned začali koupat. Měli teď vlastní bazének.` },
        { t: `Takového návštěvníka ještě nikdo ${c.inTown} neviděl.` },
        { t: `Starat se o dinosaura je velká práce. Kamínka bylo potřeba nakrmit, napojit, podrbat za ušima, i když žádné uši neměl, a hlavně ho uhlídat, aby nešlápl do záhonu.` },
        { t: `${c.H} to ${c.g('zvládal', 'zvládala', 'zvládali')} skvěle.` },
        { t: `Pak si hráli na schovávanou. Jenže schovat dinosaura není vůbec jednoduché. Za keřem mu koukal ocas. Za kůlnou hlava. A za popelnicí úplně všechno. Kamínek ale pokaždé zavřel oči a myslel si, že když nevidí on, nevidí ani nikdo jiný.` },
        { t: `Odpoledne přiběhly děti z ulice. Kamínek si lehl do trávy a z jeho ocasu se stala ta nejlepší klouzačka na světě. Nahoru po zádech, mezi ostny, a pak šups dolů po ocase až do trávy. Znovu! A ještě jednou!` },
        { t: `Pak mu ${c.g('nakreslil', 'nakreslila', 'nakreslili')} křídou na chodník zvíře, které ${c.n('má', 'mají')} ze všech nejradši: ${c.animal}.` },
        { t: `Kamínek si obrázek dlouho prohlížel a pak ho jemně olízl. Asi to znamenalo, že se mu moc líbí. Bohužel ho tím taky celý smazal.` },
        { t: `Pak začalo krápat. Malé letní kapky, ťap, ťap. Děti se rychle schovaly Kamínkovi pod bříško, jako pod velkou zelenou stříšku. Bylo tam sucho a teplo, a když Kamínek dýchal, celá stříška se pomalu zvedala a klesala.` },
        { t: `Paní z protějšího domu přinesla hlávku zelí. „Pro toho vašeho zeleného,“ řekla. „Ať nemá hlad.“ Kamínek zelí spořádal na jedno kousnutí a paní se poklonil tak hluboko, až se nosem dotkl chodníku.` },
        { t: `Napít se chtěl Kamínek z bazénku. Nahnul se, srkl a bazének byl prázdný. Zůstala v něm jen gumová kachnička a vypadala dost překvapeně.` },
        { t: `Pak mu udělali sprchu hadicí. Kamínek byl nadšený. Výskal, točil se dokola a ocasem shodil ze šňůry celé prádlo. Jedna ponožka přistála až na komíně a možná tam visí dodnes.` },
        { t: `A když Kamínek kýchl, pokropil celou zahradu. Rajčata, okurky i květiny. „Aspoň dneska nemusíte zalévat,“ zasmál se soused přes plot.`, sfx: 'wind' },
        { t: `Odpoledne si Kamínek lehl do stínu pod jabloní. Byl už velký jako dodávka a ze všech sil se snažil být malý. Stočil se, schoval hlavu pod ocas a tiše, smutně pípal.` },
        { t: `${c.H} si ${c.g('sedl', 'sedla', 'sedli')} vedle něj.` },
        { t: `Pohladil${a} ho po čumáku a zeptal${a} se: „Copak je ti, Kamínku?“` },
        { t: `Kamínek ukázal tlapkou na skořápku. Na jejích střípcích byly zvláštní obrázky: kapradiny, sopka s obláčkem kouře a veliký dinosaurus s dlouhým krkem. Kolem toho největšího obrázku bylo nakreslené srdíčko.` },
        { t: `Kamínek se na ten obrázek díval dlouho a dlouho. Pak položil hlavu do trávy a z oka mu skanula slza. Velká jako švestka. Kapla do bazénku a v bazénku bylo zase trochu vody.` },
        { t: `I velcí dinosauři jsou totiž někdy malí. Hlavně když se jim stýská.` },
        { t: `„To je tvoje maminka, viď?“ ${c.g('pochopil', 'pochopila', 'pochopili')} hned. Kamínek smutně kývl. Stýskalo se mu. Patřil do jiného času, do doby, kdy po světě chodili dinosauři.` },
        { t: `Aby ho trochu potěšil${a}, ${c.g('zazpíval', 'zazpívala', 'zazpívali')} mu písničku. Tichou, pomalou, takovou, jakou se zpívá před spaním. Kamínek přestal pípat a poslouchal. A na chvilku přestal být smutný.` },
        { t: `Jak se ale dostat do pravěku? Žádný vlak tam nejede. Autobus taky ne. A letadlo už vůbec ne.` },
        { t: `${c.H} ${c.g('přemýšlel', 'přemýšlela', 'přemýšleli')}.` },
        { t: `Přemýšlel${a} tak usilovně, až ${c.g('se mu', 'se jí', 'se jim', 'se jim')} z hlavy skoro kouřilo. A pak si všiml${a} jedné věci.` },
        { t: `Na skořápce, úplně dole, byla vyrytá spirála. Točitá čára, jako šnečí ulita. A úplně stejnou spirálu už přece někde viděl${a}. Na starém kameni v rohu zahrady, za kompostem. Ten kámen tam ležel odjakživa a nikdo nevěděl, kdo ho tam dal.` },
        { t: `Rozběhli se tam. Odhrnuli kopřivy, odhrnuli mech. A opravdu. Na kameni byla úplně stejná spirála. Jen uprostřed měla důlek. Malý kulatý důlek, velký přesně jako kousek skořápky.` },
        { t: `„To je klíč! Skořápka je klíč!“ ${c.g('vykřikl', 'vykřikla', 'vykřikli')} nadšeně.`, sfx: 'ding' },
        { t: `Do večera nasbírali všechny střípky skořápky. Některé byly v trávě, některé v záhonu a jeden měl Kamínek přilepený na ocase. Poskládali je dohromady jako puzzle. Chyběl jen jeden kousek. Ten se spirálou.` },
        { t: `Slunce zapadalo a obloha zrůžověla.` },
        { t: `Pak ${c.H} ${c.g('položil', 'položila', 'položili')} poslední střípek do důlku v kameni.` },
        { t: `Kámen zabzučel. Nejdřív potichu, jako čmelák. Pak víc, jako lednička. Spirála se rozsvítila zlatým světlem a začala se točit. Točila se a točila, až se ve vzduchu nad kamenem otevřelo kulaté okno.`, sfx: 'magic' },
        { t: `Oknem byla vidět úplně jiná krajina. Obrovské kapradiny, vyšší než dům. Teplé jezero, ze kterého stoupala pára. V dálce sopka s klidným bílým obláčkem. A vzduch, který k nim proudil, voněl deštěm a mokrým listím.` },
        { t: `Kamínek stál u okna a nohy se mu trochu třásly. Bylo to tak veliké a tak neznámé.` },
        { t: `„Neboj se. ${c.n('Jsem', 'Jsme')} tady s tebou,“ ${c.g('pošeptal', 'pošeptala', 'pošeptali')} mu do ostnů. „Za tím oknem na tebe někdo čeká.“` },
        { t: `Na břehu jezera stála veliká dinosauří maminka s dlouhým krkem. Rozhlížela se a volala: „Húúú, húúú.“ Hlubokým, laskavým hlasem, jako když fouká vítr do prázdné láhve.` },
        { t: `Kamínek zvedl hlavu, nadechl se z bříška, přesně jak se to naučil, a poprvé v životě opravdu zařval: „Ráááá!“ Maminka se otočila. A její oči se rozzářily štěstím.` },
        { t: `Sklonila dlouhý krk až k oknu, tak blízko, že bylo slyšet její teplý dech. Podívala se na Kamínka a pak i na zahradu a na všechny, kdo tam stáli. A tiše, vděčně zabručela.` },
        { t: `Ještě než odešel, sklonil Kamínek velikou hlavu až k zemi. Jemně šťouchl čumákem do ${c.h.gen}.` },
        { t: `Bylo to dinosauří objetí. A taky dinosauří děkuju.` },
        { t: `„Sbohem, Kamínku. Budeš ${c.n('mi', 'nám')} chybět,“ ${c.g('zašeptal', 'zašeptala', 'zašeptali')} ${c.H}.` },
        { t: `Pak Kamínek prošel kulatým oknem. Udělal dva kroky, tři kroky a byl u maminky. Maminka ho olízla po celé hlavě, až se mu ostny rozčepýřily. A Kamínek blahem zavrtěl ocasem.` },
        { t: `Okno se pomalu zavřelo. Spirála na kameni pohasla. A v rohu zahrady zase ležel jen obyčejný starý kámen, porostlý mechem.` },
        { t: `Jen v trávě po Kamínkovi zůstal jeden malý zelený osten. Měkký a lesklý jako kousek smaragdu.`, sfx: 'sparkle' },
        { t: `${c.H} ${c.g('si ho schoval', 'si ho schovala', 'si ho schovali')} pod polštář.` },
        { t: `Večer přišla pusa na dobrou noc a s ní otázka: „Myslíš, že je Kamínek v pořádku?“` },
        { t: `„Určitě. Je u maminky. A to je to nejlepší místo na světě,“ zaznělo potichu z polštáře.` },
        { t: `Ten večer byla zahrada tichá. Bazének byl prázdný, záhon s mrkví byl prázdný a na komíně visela ponožka. Ale v trávě zůstaly velké stopy a v nich se odráželo světlo hvězd.` },
        { t: `Pak ${c.H} ${c.g('usnul', 'usnula', 'usnuli')}.` },
        { t: `A celou noc ${c.g('se mu', 'se jí', 'se jim', 'se jim')} zdálo o obrovských kapradinách, o teplém jezeře a o malém zeleném dinosaurovi, který se pod dlouhým krkem své maminky spokojeně stočil do klubíčka.` },
        { t: `Kdo ví, třeba se jednou zase uvidí. Stačí najít tu správnou spirálu. A trochu počkat na západ slunce.` },
      ];
    },
  },
  {
    id: 'raketou-na-mesic',
    delka: 15,
    pro: 'm',
    pozn: 'Raketa z krabic odstartuje ze zahrady nad obcí, proletí vesmírem a přistane na Měsíci. Tam dítě potká mimozemšťana Blika, který se bojí tmy a je sám; naučí ho dívat se na hvězdy a cestou zpět vidí obec z vesmíru.',
    free: false,
    cats: ['dobro'],
    ages: [4, 9],
    mood: 'adventure',
    cover: { emoji: '🚀', g1: '#0d1b4c', g2: '#5c6bc0' },
    title: (c) => `Raketou na Měsíc`,
    text: (c) => {
      const a = c.g('', 'a', 'i', 'y');
      return [
        { t: `Na půdě, za starou skříní, ležela veliká hromada krabic. Od lednice, od pračky a od nového kola. Někdo by řekl, že jsou to jen krabice. Ale ten by se moc mýlil.` },
        { t: `${c.H} ${c.g('věděl', 'věděla', 'věděli')}, že z krabic se dá postavit cokoli.` },
        { t: `Hrad, tunel, autobus. Nebo raketa. A protože venku zrovna svítil kulatý měsíc, bylo jasné, co to bude.` },
        { t: `Velká krabice dole, menší nahoře a na špičku kornout z kartonu. Okénka byla z víček od sklenic. Křídla z krabice od pizzy. A na boku stálo velkými písmeny: Raketa.` },
        { t: `Uvnitř byl ovládací panel. Knoflíky z vršků od lahví, páčka z vařečky a velké červené tlačítko, které bylo dřív víčkem od kečupu.` },
        { t: c.p2 ? `${cap(c.p2.full)} ${c.p2.g('přidal', 'přidala')} baterku, aby bylo v raketě světlo.` : `Nakonec přibyla i baterka, aby bylo v raketě světlo.` },
        { t: `Raketa se musela ještě vyzkoušet. Ťuk na křídla, drží. Ťuk na okénka, drží. Zatřást kornoutem, drží. A ještě jeden kosmonautský zkušební skok dovnitř a ven. Všechno bylo připravené.` },
        { t: `${cap(c.p1.full)} ${c.p1.g('přinesl', 'přinesla')} na cestu svačinu.` },
        { t: `Na nejdelší výlet, jaký kdy kdo podnikl, se přece nedá letět hladový. V krabičce bylo to nejlepší, co si kosmonaut může přát: ${c.food}.` },
        { t: `Raketu postavili na zahradě, špičkou k nebi. Mezitím se setmělo a na obloze se rozsvítily první hvězdy.` },
        { t: `${c.H} ${c.g('nasadil', 'nasadila', 'nasadili')} ${c.n('helmu', 'helmy')} z cedníku.` },
        { t: `Zapnul${a} si pás. Zmáčkl${a} velké červené tlačítko. A začalo odpočítávání.` },
        { t: `Deset… devět… osm… sedm… šest… pět… čtyři… tři… dva… jedna… Start!`, pause: 2 },
        { t: `Krabice se zatřásla. Zahučela, zabručela a pak – fííí! – vystřelila k nebi.`, sfx: 'magic' },
        { t: `Ještě nikdy nikdo neletěl do vesmíru ze zahrady ${c.inTown}.` },
        { t: `Pod raketou se rychle zmenšovaly střechy, zahrady a ulice. Proletěli kolem kostelní věže, kde holubi překvapeně zatřepali křídly. Kolem kosa na anténě, který si zrovna zpíval na dobrou noc a zapomněl, kde skončil.` },
        { t: `Na sousední zahradě zrovna pan soused zaléval rajčata. Zvedl hlavu, otevřel pusu a zalil si boty. Ještě dlouho pak stál s konvičkou v ruce a díval se k nebi.` },
        { t: `Pak skrz mraky. Mraky byly vlhké a studené, jako cukrová vata z lednice. A pak byli nad nimi.` },
        { t: `Kolem proletělo letadlo. Pilot vykoukl z okénka, protřel si oči a zamával. Raketu z krabic ještě nikdy neviděl.` },
        { t: `O kus výš kolem nich proletěla družice. Lesklá, s velkými křídly ze zrcátek. Pípala „píp, píp, píp“, protože posílá dolů na Zemi zprávy o počasí. Tentokrát poslala zprávu: „Nad zahradou letí raketa z krabic. Bez deště.“` },
        { t: `A pak se obloha změnila. Byla čím dál tmavší, až byla úplně černá, jako samet. A na ní svítily hvězdy. Tisíce a tisíce hvězd. Mnohem víc, než je vidět ze zahrady.`, sfx: 'sparkle' },
        { t: `V raketě najednou všechno začalo létat. Svačina, cedník, dokonce i jedna ponožka, která se tam vzala bůhví kde. Ve vesmíru totiž nic nepadá dolů. Všechno se vznáší jako bublinky ve vaně.` },
        { t: `Pak proletěli kolem vesmírné stanice. V okénku tam plavali kosmonauti v bílých oblecích. Jeden zrovna pil čaj z pytlíku a druhý se snažil chytit uletěný rohlík. Když uviděli raketu, zamávali oběma rukama i nohama.` },
        { t: `${c.H} se ${c.g('vznášel', 'vznášela', 'vznášeli')} taky.` },
        { t: `Udělal${a} kotrmelec. Pak dva. Pak se smál${a} tak, že se musel${a} chytit stropu, aby ${c.g('neodletěl', 'neodletěla', 'neodletěli')} do kouta.` },
        { t: `Kousek od rakety proplula kometa. Měla dlouhý třpytivý ocas a zamávala jím na pozdrav. Za ní se táhly jiskřičky jako za prskavkou.` },
        { t: `A daleko, daleko v dálce bylo vidět Saturn. Velkou žlutou planetu s prstenci kolem dokola. Vypadala jako někdo, kdo si točí obručí kolem pasu a nikdy ho to nepřestane bavit.` },
        { t: `A pak se objevil Měsíc. Byl veliký, šedobílý a celý v důlcích, jako ementál. Čím blíž byli, tím byl větší. Až zabral celé okénko.` },
        { t: `Raketa zpomalila. Pomaloučku, pomaloučku dosedla na měsíční prach. Žuch. Prach se zvedl do vzduchu a pomalu, pomaloučku zase klesal.` },
        { t: `${c.H} ${c.g('otevřel', 'otevřela', 'otevřeli')} dvířka.` },
        { t: `Opatrně ${c.g('vystrčil', 'vystrčila', 'vystrčili')} jednu nohu, pak druhou. A ${c.g('stál', 'stála', 'stáli')} na Měsíci!` },
        { t: `Na Měsíci se chodí legračně. Stačí se odrazit jen trošku a už letíš vysoko, jako na trampolíně. Hop, a jsi nad kamenem. Hop, a jsi nad kráterem. Hop, a skoro se dotkneš hvězd.` },
        { t: `A na Měsíci je zvláštní ticho. Žádné auto, žádný pes, žádný vítr. Jen ticho, měkké a hluboké, jako když se zaboříš hlavou do peřiny.` },
        { t: `Kousek od rakety ležel měsíční kámen. Šedý, s jiskřičkami, jako by byl posypaný cukrem. A vedle něj kráter tak hluboký, že kdyby se do něj hodil míč, letěl by dolů celou věčnost. Pomalu, jako peříčko.` },
        { t: `V jemném stříbrném prachu zůstávaly stopy. Ty tam zůstanou navždy, protože na Měsíci nefouká vítr, který by je zavál.` },
        { t: `Na obzoru Měsíce pak vycházela Země. Modrá a bílá, jako veliká skleněná kulička. Odtud vypadala docela malá. Skoro by se vešla do dlaně.` },
        { t: `Vtom se za jedním kamenem něco pohnulo. A ozvalo se tiché fňukání.` },
        { t: `Za kamenem seděl mimozemšťan. Byl malý, kulatý a modrý jako borůvka. Měl tři očka na stopkách a dvě anténky, na kterých svítila světýlka. Jenže svítila jen slabounce, jako baterka, které dochází síla.` },
        { t: `„Ahoj, ${c.n('já jsem', 'my jsme')} ${c.H}. A kdo jsi ty?“` },
        { t: `„Já jsem Blik,“ špitl mimozemšťan. „Bydlím tady na Měsíci. Jenže Měsíc se teď otáčí do tmy a já se tmy strašně bojím.“` },
        { t: `Blik vysvětlil, jak to s ním je. Když je kolem tma, jeho anténky strachy zhasínají. A když zhasnou, je tma ještě větší. A on se bojí ještě víc. A anténky zhasínají ještě víc.` },
        { t: `„A navíc jsem tu úplně sám,“ dodal smutně. „Nemám tu žádného kamaráda. Jen kameny. A kameny moc nemluví.“` },
        { t: `Na to byla jen jedna odpověď. „Tak teď už sám nejsi. Teď ${c.n('máš mě', 'máš nás')}.“` },
        { t: `Blik zamrkal všema třema očkama. Ještě nikdy mu nikdo nic takového neřekl. Jeho anténky se maličko, úplně maličko rozsvítily.` },
        { t: `${c.H} si ${c.g('sedl', 'sedla', 'sedli')} vedle Blika do prachu.` },
        { t: `Chvíli nic ${c.g('neříkal', 'neříkala', 'neříkali')}. Kamarádi totiž někdy jen tak sedí vedle sebe. A už to pomáhá.` },
        { t: `Pak Blik ukázal, kde bydlí. V malém kráteru měl domeček z kamínků a místo postele měkkou hromádku měsíčního prachu. A na prahu spala jeho měsíční kočička. Byla stříbrná, kulatá a místo předení tiše cinkala.` },
        { t: `Pak ${c.g('ukázal', 'ukázala', 'ukázali')} nahoru. Na černé obloze visela veliká modrá koule s bílými obláčky. Země.` },
        { t: `„Vidíš, Bliku? Tam ${c.n('bydlím', 'bydlíme')}. A víš, co je tam v noci? Taky tma. Ale my na tmu máme fígl.“` },
        { t: `„Jaký fígl?“ zeptal se Blik a všechna tři očka se zvědavě natáhla.` },
        { t: `„Ve tmě se díváme nahoru, na hvězdy. Hvězdy svítí jenom ve tmě. Kdyby nebyla tma, nikdy bychom je neviděli. Tma je vlastně velká černá tabule, na kterou se kreslí hvězdami.“` },
        { t: `Blik se podíval nahoru. A opravdu. Čím víc se Měsíc otáčel do tmy, tím víc hvězd se rozsvěcelo. Jedna, deset, sto, milion. Celá obloha se třpytila.` },
        { t: `„Tamhle ta velká je Večernice. A tamhle ty, co vypadají jako vůz s ojí, se jmenují Velký vůz. Když je najdeš, nikdy se v noci neztratíš.“ Blik opakoval jména hvězd tiše, jako by to byla kouzelná slova.` },
        { t: `A pak se stalo něco zvláštního. Blikovy anténky se rozsvítily. Nejdřív slabě, pak víc a nakonec svítily jako dvě malé lampičky. Kdo se nebojí, tomu totiž anténky svítí naplno.`, sfx: 'ding' },
        { t: `„Já svítím!“ zvolal Blik a radostí udělal kotrmelec, až vyletěl vysoko nad kráter. „Já ve tmě svítím!“` },
        { t: `Pak si spolu hráli. Skákali přes krátery, kreslili prstem do prachu a hráli si na schovávanou. Blika bylo vždycky snadné najít, protože jeho anténky svítily jako dvě světlušky.` },
        { t: `Potom spolu spojovali hvězdy do obrázků. Tady jeden vůz, tamhle konvička, a tamhle dlouhý had. A nakonec spojili hvězdy do tvaru zvířete, které ${c.n('má', 'mají')} ${c.H} nejradši: ${c.animal}.` },
        { t: `Blik nadšeně tleskal všema čtyřma ručičkama. Takové hvězdné zvíře ještě nikdy neviděl. Prý mu bude každou noc svítit nad domečkem.` },
        { t: `Nakonec se rozdělili o svačinu. Blik ochutnal pozemské jídlo poprvé v životě. Mlaskal, olizoval se a anténky mu blahem blikaly jako vánoční stromeček.` },
        { t: `Ale pak bylo načase letět domů. „Musím letět, Bliku. Doma ${c.n('mě', 'nás')} čekají.“` },
        { t: `Blik posmutněl. „A ${c.n('přiletíš', 'přiletíte')} zase?“ zeptal se tiše.` },
        { t: `„Určitě. A až se v noci ${c.n('podívám', 'podíváme')} na Měsíc, ${c.n('zamávám', 'zamáváme')} ti. A ty ${c.n('mi', 'nám')} zablikáš anténkami. Platí?“` },
        { t: `„Platí!“ zablikal Blik. A to byl jejich tajný pozdrav.` },
        { t: `Na památku dostal${a} od Blika měsíční kamínek. Byl malý, hladký a ve tmě svítil slabým stříbrným světlem. „${c.g('Kdyby ses někdy ve tmě bál', 'Kdyby ses někdy ve tmě bála', 'Kdybyste se někdy ve tmě báli', 'Kdybyste se někdy ve tmě bály')}, ${c.n('podívej', 'podívejte')} se na něj,“ řekl Blik. „Já tady svítím taky.“` },
        { t: `Raketa se zatřásla a vzlétla. Blik dole mával a jeho anténky svítily jako maják. Byl čím dál menší, a menší, až z něj zbyla jen malinká modrá tečka na šedém Měsíci.`, sfx: 'wind' },
        { t: `Cestou domů ${c.g('se díval', 'se dívala', 'se dívali')} z okénka. Země byla čím dál větší. Moře byla modrá, lesy zelené a mraky bílé jako peřiny.` },
        { t: `Když vlétli do vzduchu kolem Země, raketa se trochu zahřála, jako hrnek čaje v dlaních. Zahučela, zabrumlala a pak zpomalila. A znovu proletěli mraky, tentokrát shora dolů.` },
        { t: `Pak se pod nimi objevila světýlka. Spousta malých světýlek v noční tmě. To byly vesnice a města, kde lidé zrovna večeří, čtou si nebo chodí spát.` },
        { t: c.near.length ? `Někde tam svítí ${listCz(c.near.slice(0, 3))}.` : `Někde tam svítí i všechny vesnice a města z okolí.` },
        { t: `Ulice ${c.inTown} svítily jako zlatý náhrdelník.` },
        { t: `A uprostřed všech těch světýlek svítil domov. Docela malý, docela obyčejný, a přece ten nejkrásnější na celé Zemi.` },
        { t: `Raketa zpomalila, prolétla mraky a tiše přistála na zahradě. Žuch. Přesně vedle záhonu.` },
        { t: `${cap(c.p1.nom)} už ${c.p1.g('stál', 'stála')} ve dveřích.` },
        { t: `„Tak co, ${c.g('kosmonaute', 'kosmonautko', 'kosmonauti', 'kosmonautky')}? Jak bylo na Měsíci?“` },
        { t: `„Báječně. ${c.n('Mám', 'Máme')} tam kamaráda,“ ${c.g('odpověděl', 'odpověděla', 'odpověděli')} se zívnutím.` },
        { t: `Před spaním se ještě ${c.g('podíval', 'podívala', 'podívali')} z okna. Na nebi svítil Měsíc. A na něm, když se člověk dívá hodně pozorně, blikla dvě malinká světélka. Jednou, dvakrát.`, sfx: 'sparkle' },
        { t: `${c.H} ${c.g('zamával', 'zamávala', 'zamávali')}.` },
        { t: `Měsíční kamínek si ${c.g('položil', 'položila', 'položili')} na noční stolek. Svítil jen trošičku, jako malinká noční lampička. Akorát tolik, aby se v pokoji dobře usínalo.` },
        { t: `Za oknem pomalu pluly mraky. Měsíc nad nimi svítil klidně a stříbrně. A kdyby se někdo díval hodně, hodně pozorně, viděl by, jak se na něm občas něco modře zatřpytí.` },
        { t: `Raketa z krabic stála na zahradě a odpočívala. Hvězdy svítily. A někde daleko nahoře spal na hromádce měsíčního prachu malý modrý kamarád.` },
        { t: `Dobrou noc, Bliku. Dobrou noc, Měsíci. A dobrou noc, ${c.h.voc}.` },
      ];
    },
  },
  {
    id: 'ponorka-pod-rybnikem',
    delka: 15,
    pro: 'vse',
    pozn: 'Malá žlutá ponorka vezme dítě pod místní rybník mezi kapry, raka a hodného popleteného vodníka Šplíchala, který ztratil klíč od rybničních vrátek. Klíč se najde u raka, který ho měl za zrcátko, a po otevření vrátek se rozsvítí podvodní světélka.',
    free: false,
    cats: ['dobro', 'zvirata'],
    ages: [4, 9],
    mood: 'adventure',
    cover: { emoji: '🐟', g1: '#004d40', g2: '#4dd0e1' },
    title: (c) => `Ponorka pod rybníkem`,
    text: (c) => {
      const a = c.g('', 'a', 'i', 'y');
      const kap = c.g('kapitáne', 'kapitánko', 'kapitáni', 'kapitánky');
      return [
        { t: `Za obcí je rybník. Ve dne se na něm houpou kachny, na břehu sedí rybáři a večer tam kuňkají žáby. Ale co je pod hladinou, to ještě nikdo pořádně neviděl.`, sfx: 'birds' },
        { t: `${cap(c.inTown)} se o tom rybníku vypráví spousta věcí.` },
        { t: `Prý je tam vodník. Prý je dno z čistého zlata. A prý se tam kdysi ztratila bota pana hajného a už se nikdy nenašla.` },
        { t: `Jednoho slunečného rána ${c.g('šel', 'šla', 'šli')} ${c.H} kolem rybníka.` },
        { t: `U břehu, mezi rákosím, se něco žlutě lesklo. Byla to malá ponorka. Kulatá jako vejce, s okénky jako kulaté brýle a s vrtulkou vzadu. Na boku měla nápis: „Pro malé kapitány.“` },
        { t: `Kdo by odolal? Poklop byl otevřený a uvnitř bylo místo přesně pro ${c.g('jednoho malého kapitána', 'jednu malou kapitánku', 'malou posádku', 'malou posádku')}. Kormidlo, kulatá okénka a spousta knoflíků.` },
        { t: `${c.H} ${c.g('vlezl', 'vlezla', 'vlezli')} dovnitř a ${c.g('zavřel', 'zavřela', 'zavřeli')} poklop.` },
        { t: `Cvak. Uvnitř to vonělo jako nová gumová kachnička. Vedle kormidla visela cedulka: „Zelené tlačítko – dolů. Modré tlačítko – nahoru. Žluté tlačítko – světla.“` },
        { t: `Na poklopu ještě seděla žába. Zelená, vypoulená a důležitá. „Kuňk,“ řekla. „Svezu se kousek s vámi. Ráda koukám do okýnek.“ A přitiskla se k okénku jako přísavka.` },
        { t: `Zmáčkl${a} zelené. Ponorka zabublala, zahoupala se a pomalu se ponořila pod hladinu. Blub, blub, blub.` },
        { t: `Pod vodou bylo zeleno a ticho. Paprsky slunce se ve vodě lámaly jako zlaté nitky. Kolem okének stoupaly bublinky, malé a stříbrné jako perličky.` },
        { t: `Pod vodou je slyšet úplně jiné zvuky než nahoře. Bublinky pukají, rákos šustí a odněkud z dálky je slyšet žabí koncert, jen tišší, jako by žáby zpívaly do polštáře.` },
        { t: `První, kdo připlaval, byl kapr. Velký, kulatý, se šupinami jako zlaté mince a s vousky, které se mu kroutily jako knírek. Zíral do okénka a otvíral pusu: pup, pup, pup.` },
        { t: `Za ním připlul druhý kapr, pak třetí, a za chvíli kolem ponorky kroužilo celé hejno. Kapři jsou zvědaví. A taky trochu mlsní. Kdo ví, jestli si nemysleli, že je ponorka veliký žlutý rohlík.` },
        { t: `U velkého kamene stála štika. Dlouhá, štíhlá a s přísným pohledem. Vypadala trochu jako paní učitelka. Ale nebyla zlá. Byla to rybniční dopravní policistka a ploutví ukazovala malým rybkám, kdy smějí plavat přes cestu.` },
        { t: `„Pomalu, pomalu,“ řekla štika ponorce. „Tady plavou rybí školky.“ A celá řada malinkých rybiček se za ní seřadila jako děti na výletě, jedna za druhou.` },
        { t: `Žába na poklopu se mezitím rozloučila. „Tady vystupuju,“ kuňkla, odrazila se a odplavala k leknínu. Plavala krásně, nožičkama dozadu, jako když se plave prsa.` },
        { t: `Nejstarší kapr se jmenoval děda Šupina. Byl tak starý, že si pamatoval, kdy byl rybník ještě louže.` },
        { t: `„Vítej${c.n('', 'te')}, ${kap}. ${c.g('Přijel jsi', 'Přijela jsi', 'Přijeli jste', 'Přijely jste')} právě včas, protože máme velkou starost,“ zabublal děda Šupina.` },
        { t: `A pak vysvětlil, o co jde. Na konci rybníka jsou rybniční vrátka. Každý večer se otevřou a do rybníka přiteče čerstvá voda z potoka. Voda pak voní, bublá a ryby mají čím dýchat. Jenže vrátka jsou zamčená. A klíč se ztratil.` },
        { t: `„Klíč má na starosti vodník Šplíchal,“ bublal kapr. „Je to moc hodný vodník. Jenom trochu… popletený.“` },
        { t: `Kolem proplula plotice a hned se přidala: „Minulý týden si oblékl kabát naruby. A předtím chtěl zalévat lekníny. Pod vodou!“ A smála se tak, až jí ze žaber vyletěly bublinky.` },
        { t: `Ponorka plula dál, nad podvodními loukami. Rostly tam dlouhé zelené řasy, které se vlnily jako vlasy ve větru. Mezi nimi poskakovaly malé rybičky a hrály si na honěnou.` },
        { t: `Pak se před nimi objevil domeček. Postavený z kamenů a mušlí, se střechou z leknínových listů a s komínem, ze kterého místo kouře stoupaly bublinky.` },
        { t: `Před domečkem pobíhal vodník. Malý, kulatý, v zeleném kabátku, ze kterého mu kapala voda, i když byl pod vodou. Na hlavě měl klobouček s pentlí a tvářil se, jako by se mu něco hrozně nepovedlo.` },
        { t: `„Kde jen může být? Kde jen může být? Dal jsem ho pod polštář. Nebo do hrnečku. Nebo jsem ho snědl? Ne, klíče se přece nejí,“ mumlal vodník a obracel kameny.` },
        { t: `${c.H} ${c.g('zmáčkl', 'zmáčkla', 'zmáčkli')} knoflík s nápisem mluvítko.` },
        { t: `„Dobrý den, pane vodníku. ${c.n('Můžu', 'Můžeme')} vám pomoct hledat?“` },
        { t: `Vodník se lekl tak, že mu klobouček vyletěl nahoru a pomalu se snášel zpátky. „Jé, návštěva! A v ponorce! To jsem neviděl od doby, kdy jsem byl malý vodníček.“` },
        { t: `„A ty jsi kdo? Pepíček? Mařenka? Nebo snad ten kapr z vedlejší tůňky?“ vyptával se vodník.` },
        { t: `„${c.n('Já jsem', 'My jsme')} ${c.H}.“` },
        { t: `„No jistě. Hned jsem to říkal,“ přikývl vodník, i když to vůbec neříkal. Takový on už prostě je.` },
        { t: `Děda Šupina zatím vyprávěl, jak to bylo, když se vrátka otevírala naposledy. Voda z potoka přitekla s takovou radostí, že pošimrala všechny kapry na bříšku. A celý rybník se pak smál ještě do rána.` },
        { t: `„Hledal jsem v domečku. Hledal jsem v rákosí. Hledal jsem dokonce i v hrnečku na bonbóny. A nikde nic,“ naříkal vodník.` },
        { t: `Vodníkův domeček byl uvnitř plný hrnečků. Velké, malé, s puntíky i s proužky. V jednom měl bonbóny, v druhém knoflíky, ve třetím sbírku pěkných kamínků. A ve čtvrtém si schovával vlastní radost, aby mu ji nikdo nevzal.` },
        { t: `Tak hledali spolu. Nejdřív v bahně na dně. Ponorka rozsvítila světla a ta prořízla zelenou vodu jako dva dlouhé zlaté paprsky.` },
        { t: `V bahně našli hrnek bez ucha, žlutou kachničku, starou podkovu a – ejhle – botu pana hajného! Ale klíč ne.` },
        { t: `Pak zkusili velkou škebli. Škeble se pomalu otevřela, zívla a zase zaklapla. „Nemám,“ zamumlala. „Já mám jen perličku. A tu nedám.“` },
        { t: `Pak připluli ke staré loďce, která ležela na dně už sto let. Celá byla zarostlá řasami a uvnitř bydlela rodina okounů. Okouni loďku prohledali od přídě až po záď. Našli tři knoflíky a jednu lžičku. Ale klíč ne.` },
        { t: `Pak prohledali rákosí. Mezi stébly visely vodníkovy brýle, které hledal už od jara, a jeho druhý klobouček, který hledal od zimy. Vodník byl nadšený. Ale klíč tam taky nebyl.` },
        { t: `Vodník si nasadil nalezené brýle a hned viděl všechno ostřeji. Ryby, kameny i ponorku. Jen klíč pořád neviděl. „Možná se schovává,“ řekl. „Klíče se rády schovávají. Hlavně když je člověk potřebuje.“` },
        { t: `„A kde jste vlastně byl včera, pane vodníku?“ ${c.g('zeptal', 'zeptala', 'zeptali')} se chytře. Vodník se zamyslel. „Včera? Včera jsem… počítal kapry. Pak jsem zaléval lekníny. A pak… pak už nevím.“` },
        { t: `Pod kořenem staré vrby bydlel rak Rudolf. Rak chodí pozpátku, a tak i odpovídá trochu pozpátku. Nejdřív řekne konec a pak začátek.` },
        { t: `„Neviděl jsem, klíč žádný. Klíč? Klíč, klíč,“ opakoval rak a couval do své díry. „Mám jen nové zrcátko.“` },
        { t: `A z díry vystrčil klepeto. V klepetu se lesklo něco zlatého. Rak se v tom natáčel, kroutil tykadly a obdivoval se.` },
        { t: `${c.H} se ${c.g('zadíval', 'zadívala', 'zadívali')} pozorněji.` },
        { t: `Tohle nebylo zrcátko. Bylo to zlaté, mělo to kroužek a na konci zoubky. „To je přece ten klíč!“` },
        { t: `Rak se zarazil. „Klíč? Ach jo. Já myslel, že je to zrcátko. Vždyť se v něm tak hezky vidím.“ A smutně sklopil tykadla. Nechtěl o své zrcátko přijít.` },
        { t: `Vtom ${c.g('dostal', 'dostala', 'dostali')} ${c.H} nápad.`, sfx: 'ding' },
        { t: `Nad kormidlem ponorky bylo malé kulaté zrcátko. Kapitán ho potřebuje jen málokdy. Opatrně ho ${c.g('odšrouboval', 'odšroubovala', 'odšroubovali')} a mluvítkem ${c.g('zavolal', 'zavolala', 'zavolali')}: „Pane raku, co kdybychom si to vyměnili?“` },
        { t: `Rak se podíval do nového zrcátka. Bylo kulaté, čisté a byla v něm vidět obě klepeta naráz. „Tohle je ještě lepší!“ zvolal a klíč s radostí vrátil.` },
        { t: `Vodník Šplíchal se radostí roztočil dokola, až se mu šosy kabátku zatočily jako vrtulka. „Ááá, už vím! Včera jsem si u vrby zdříml a klíč mi vyklouzl z kapsy. Já jsem ale popleta!“` },
        { t: `Pak pluli ke vrátkům všichni spolu. Vodník vpředu, ponorka za ním, za ponorkou hejno kaprů a úplně vzadu rak Rudolf. Pozpátku, samozřejmě. Aby se mohl cestou dívat do zrcátka.` },
        { t: `U vrátek se vodník zastavil a slavnostně smekl klobouček. „Čest otevření patří ${c.g('kapitánovi', 'kapitánce', 'kapitánům', 'kapitánkám')}.“` },
        { t: `Ponorka měla vpředu malé kovové klepítko, skoro jako rak. Do klepítka se vložil klíč, pak do zámku, a pak otočit. Cvak.` },
        { t: `Vrátka se otevřela. Do rybníka se vlila čerstvá voda z potoka. Chladná, čistá a plná bublinek. Ryby se do ní vrhly, jako když děti skáčou do bazénu.` },
        { t: `A pak se stalo něco krásného. Na dně rybníka se začala rozsvěcet světélka. Malé zelené, modré a fialové lampičky. To byly podvodní řasy, které svítí, když dostanou čerstvou vodu.`, sfx: 'sparkle' },
        { t: `Celý rybník zářil jako noční město. Kapři mezi světélky pluli pomalu a slavnostně, jako na plese. Šneci si rozsvítili ulity. A škeble se pootevřela, aby i její perlička viděla tu krásu.` },
        { t: `Kapři začali tančit. Kroužili kolem ponorky, nahoru a dolů, a jejich šupiny se ve světle řas leskly jako stovky malých zrcátek. Rak Rudolf tančil taky. Pozpátku, ale s velikou chutí.` },
        { t: `Žába z poklopu kuňkala do rytmu a vodník tleskal, až mu z kabátku stříkaly kapky. Tak veselý večer pod rybníkem nikdo nepamatoval. Ani děda Šupina.` },
        { t: `Nakonec se děda Šupina nabídl, že ponorku doprovodí až k hladině. Plul vedle ní pomalu a důstojně, jako velká zlatá loď, a cestou vyprávěl, co všechno ještě v rybníku je k vidění. Na příště.` },
        { t: `„Tohle se stane jen jednou za rok. Když se vrátka otevřou ve správnou chvíli. A dneska je ta správná chvíle. Díky ${c.n('tobě', 'vám')},“ šeptal vodník.` },
        { t: `Na rozloučenou dal vodník do ponorky malou mušličku. „Až ${c.n('ji přiložíš', 'ji přiložíte')} k uchu, ${c.n('uslyšíš', 'uslyšíte')} náš rybník.“` },
        { t: `Pak přišlo na řadu modré tlačítko. Ponorka vyplula nahoru, blub, blub, blub, a vynořila se mezi lekníny. Slunce už zapadalo a nad rybníkem se honily vlaštovky.` },
        { t: `${c.H} ${c.g('vylezl', 'vylezla', 'vylezli')} na břeh.` },
        { t: `Ještě jednou se ohlédl${a}. Ponorka tiše zabublala a schovala se do rákosí. Bude tam čekat na dalšího malého kapitána.` },
        { t: `Doma už ${c.p1.g('čekal', 'čekala')} ${c.p1.full}.` },
        { t: `„Kdepak ${c.g('ses toulal', 'ses toulala', 'jste se toulali', 'jste se toulaly')}?“` },
        { t: `„Pod rybníkem.“ A byla to pravda.` },
        { t: `K večeři bylo to nejlepší jídlo na světě: ${c.food}.` },
        { t: `V noci ${c.g('si přiložil', 'si přiložila', 'si přiložili')} mušličku k uchu. Šumělo v ní tiše a hluboce. Žbluňk, žbluňk. Pup, pup. A někde daleko se ozval tichý hlas: „Dobrou noc, ${kap}.“` },
        { t: `Někde za obcí teď spí rybník. Kapři odpočívají na dně, rak Rudolf se ještě naposledy podívá do zrcátka a vodník Šplíchal si zase zapomněl, kam si dal klobouček. Ale klíč má tentokrát pověšený na krku.` },
        { t: `Dobrou noc, ${c.h.voc}.` },
      ];
    },
  },
]);
